      "summary": "汉 · 金银器 · 馆藏",
      "cardLead": "两峰骆驼以对称轮廓压缩在金牌饰上，动物母题与贵金属加工共同指向北方草原的装饰传统。",
      "essay": [
        {
          "heading": "器物与形制",
          "text": "双驼纹金牌饰以薄金片构成近长方形牌面，两峰骆驼相向或并列于有限空间之中。工匠依靠压印、錾刻和边缘修整突出驼峰、颈部与四肢，轮廓既要足以识别动物，也要适应缀附在衣物、带具或其他载体上的实际结构。"
        },
        {
          "heading": "草原交通的图像",
          "text": "骆驼是欧亚内陆远距离运输的重要畜力，进入金牌饰后又成为身份、财富与移动生活的象征。双驼母题把动物形象、贵金属工艺和北方草原装饰传统压缩在一件小型饰物上；其意义不在于笼统证明“丝路交流”，而在于具体展示一种交通动物怎样被转化为可佩戴的视觉标志。"
        }
      ],
