          "text": "库思老二世在位于公元 590—628 年，正值萨珊银币大量铸造和远距离传播的阶段。币面把君主肖像与祭火坛并置，使国家权力、宗教秩序和支付尺度在一枚小型圆片上同时出现；它在中国收藏与考古语境中的价值，正在于为隋唐时期中国与伊朗高原之间的人员、商品和货币流动提供可辨识的实物参照。"
