      "tags": [],
      "tagsText": "",
      "summary": "唐 · 玉石器 · 西安市兴庆宫遗址出土",
      "cardLead": "这件唐代玉石器出土于西安市兴庆宫遗址。价值集中在选料、切割、钻孔、磨治和抛光形成的轮廓。",
      "essay": [
        {
          "heading": "器物与形制",
          "text": "这件唐代玉石器出土于西安市兴庆宫遗址。价值集中在选料、切割、钻孔、磨治和抛光形成的轮廓。玉石质地坚硬，细微的弧度与孔道往往需要长时间加工；天然色带、绺裂和表面磨痕也应与器形一起观察，而不能只以颜色判断品质。"
        },
        {
          "heading": "历史意义",
          "text": "隋唐长安连接宫廷、市场、宗教场所和交通路线。原料、器形与装饰技法的迁移，会在宴饮、出行、信仰和日常用具中留下具体变化。莲花纹石柱础所用石材的来源、切磨耗时与使用磨痕，可帮助区分实用器、陈设品和身份用品；天然纹理也会影响工匠安排器形。"
        }
      ],
      "evidence": "名称、时代与来源优先取自 DSC_4333 中与画面中心器物对应的展签；说明牌只用于文字提取，不作为文物图片展示。可见器物图为 DSC_4331—DSC_4332，现场原片保存在 F:\\DCIM\\102NCZ_F。",
