      "cardLead": "鸳鸯莲瓣纹金碗是唐代金银器中极具代表性的器物，出土于西安市何家村窖藏。碗的功能并不止于陈设：唐代文献与同窖藏出土的舞马衔杯纹皮囊式银壶共同提示，它也可能实际参与过饮酒与宴饮。",
      "essay": [
        {
          "heading": "器物与形制",
          "text": "鸳鸯莲瓣纹金碗是唐代金银器中极具代表性的器物，出土于西安市何家村窖藏。碗的功能并不止于陈设：唐代文献与同窖藏出土的舞马衔杯纹皮囊式银壶共同提示，它也可能实际参与过饮酒与宴饮。碗壁以捶揲工艺形成起伏的莲瓣，瓣间与器内外的纹饰共同制造出圆满、绵密的节奏；鸳鸯纹把成对、和合的吉祥语义压进金属表面。器物的重量、弧腹和花瓣起伏，说明工艺并没有让金属失去体量感。"
        },
        {
          "heading": "文化影响",
          "text": "这类金碗把宫廷宴饮、金银器工艺与外来装饰传统连在一起。莲瓣纹的立体起伏在地中海、西亚和中亚金银器传统中均可找到远近关系，唐代工匠对其进行本土化转写，留下了跨区域工艺交流的清晰痕迹。"
        }
      ],
