      "essay": [
        {
          "heading": "器物与形制",
          "text": "这件唐代陶器出土于西安市东郊王家坟唐墓。仿照木柜塑成：长方形柜体架在四足之上，正面设门、锁扣和成组乳钉，顶面及边框分区施釉。黄、绿、褐色釉没有铺满全器，露胎处与釉色边界清楚，可见陶胎拼接、模印附件和低温铅釉共同完成一件微缩家具。"
        },
        {
          "heading": "历史意义",
          "text": "钱柜是唐代家庭储藏钱物的家具，这件陶质模型则进入墓葬随葬系统。门扇、锁扣、乳钉和柜足被缩小后仍清楚可辨，说明制作者关心的是家具结构和财富保管方式。它补充了传世家具稀少造成的材料缺口，也留下唐人如何把日常生活搬入墓室的具体证据。"
        }
      ],
