      "summary": "唐 · 玉石器 · 西安市何家村窖藏出土",
      "cardLead": "玛瑙长杯为唐代何家村窖藏出土器。杯体横向舒展，浅腹与低足共同形成适合双手持取的比例；天然玛瑙的色带、透明度和内部纹理随着弧面变化，工匠需要顺应原料裂隙和层理确定杯口、腹壁与足部的位置。",
      "essay": [
        {
          "heading": "器物与材质",
          "text": "玛瑙长杯为唐代何家村窖藏出土器。杯体横向舒展，浅腹与低足共同形成适合双手持取的比例；天然玛瑙的色带、透明度和内部纹理随着弧面变化，工匠需要顺应原料裂隙和层理确定杯口、腹壁与足部的位置。"
        },
        {
          "heading": "宴饮与珍宝收藏",
          "text": "何家村窖藏同时保存金银酒器、玉石器和异域风格器形，玛瑙长杯因此兼具宴饮用具与珍宝的双重属性。两件同名长杯合并展示后，可从轮廓、色带和加工痕迹比较同类器物的个体差异，也更能说明唐代上层社会如何把稀有石材纳入成组饮食器。"
        }
      ],
      "evidence": "器物图为 DSC_4455—DSC_4682；名称、时代与来源由相邻展签核对，展签画面不作为器物封面。原始照片保存在 F:\\DCIM\\102NCZ_F。",
