      "cardLead": "这件清代器物，征集。照面经磨治用于映照，镜背则以钮、钮座和同心纹带组织“湖州薛”主题。",
      "essay": [
        {
          "heading": "器物与形制",
          "text": "这件清代器物，征集。照面经磨治用于映照，镜背则以钮、钮座和同心纹带组织“湖州薛”主题。纹样并非附在功能之外：中央钮用于穿系，圆周分区顺应铸造表面，也让图像在转动镜体时依次展开。"
        },
        {
          "heading": "历史意义",
          "text": "它兼具照容、佩系和图像传播功能。镜背纹样与铭文会随时代更换，出土组合和使用磨损则说明它属于日常用具、礼物还是随葬品；同类镜的分布也可追踪铸镜技术和纹样范本的流动。"
        }
      ],
      "evidence": "名称、时代与来源优先取自 DSC_4506 中与画面中心器物对应的展签；说明牌只用于文字提取，不作为文物图片展示。可见器物图为 DSC_4505，现场原片保存在 F:\\DCIM\\102NCZ_F。",
