      "cardLead": "镀金白玉臂环为唐代装饰用玉器，出土于西安市何家村唐代窖藏。现场照片记录成对陈列的环体，随后拍到题名墙；该题名画面只承担文字证据的作用，网站卡片保留器物照片，不再把它与后面的莲瓣纹提梁银罐合并。",
      "essay": [
        {
          "heading": "器物与形制",
          "text": "镀金白玉臂环为唐代装饰用玉器，出土于西安市何家村唐代窖藏。现场照片记录成对陈列的环体，随后拍到题名墙；该题名画面只承担文字证据的作用，网站卡片保留器物照片，不再把它与后面的莲瓣纹提梁银罐合并。臂环以白玉环体为主体，外加镀金金属构件，玉石的温润光泽与金属的明亮表面形成清楚对照。成对保存使直径、厚薄、接口和装饰位置能够彼此参照，也说明这不是从一件复合器上脱落的普通环形零件。"
        },
        {
          "heading": "服饰与身份",
          "text": "何家村窖藏集中保存了金银器、玉带和身体装饰品，臂环由此进入唐代贵族服饰与珍宝收储的具体语境。它的意义不只在材料昂贵，还在于玉与镀金工艺如何共同塑造佩戴效果，并让身体装饰成为身份、财富与审美选择的可见部分。"
        }
      ],
      "evidence": "名称、时代与来源优先取自 DSC_4605 中与画面中心器物对应的展签；说明牌只用于文字提取，不作为文物图片展示。可见器物图为 DSC_4604，现场原片保存在 F:\\DCIM\\102NCZ_F。",
