      "tagsText": "music forbidden",
      "summary": "唐 · 金银器 · 西安市何家村唐代窖藏出土",
      "cardLead": "壶腹两面模压衔杯匐拜的舞马，图像对应唐玄宗千秋节随《倾杯乐》献寿的宫廷表演。",
      "essay": [
        {
          "heading": "何家村窖藏与目录身份",
          "text": "鎏金舞马衔杯纹皮囊式银壶出土于 1970 年西安何家村唐代窖藏，现藏陕西历史博物馆，并列入 2002 年首批禁止出国（境）展览文物目录。馆方题名同时指出三层信息：银质鎏金、皮囊式壶形，以及器腹的舞马衔杯主题。"
        },
        {
          "heading": "捶揲、模压与焊接",
          "text": "壶身呈扁圆形，借鉴北方游牧地区皮囊壶的外形；覆式莲瓣壶盖以银链连接弓形提梁。工匠先捶揲银板形成壶体，再在两面模压奋首鼓尾、屈膝衔杯的舞马，合拢焊接后反复打磨，接缝几乎不显，最后以鎏金突出图像。"
        },
        {
          "heading": "音乐关联与珍稀性",
          "text": "唐玄宗千秋节宴会曾以舞马祝寿，舞马按《倾杯乐》节拍起舞，高潮时衔杯跪拜。银壶并非演出现场的照相式记录，却把乐曲、受训动物、身体动作和皇帝生日仪式固定在器表；当舞马制度在安史之乱后消失，这幅可与文献互证的图像便具有罕见的音乐史价值。"
        }
      ],
      "evidence": "名称、时代与来源优先取自 DSC_4618 中与画面中心器物对应的展签；说明牌只用于文字提取，不作为文物图片展示。可见器物图为 DSC_4613—DSC_4617，现场原片保存在 F:\\DCIM\\102NCZ_F。",
