          "text": "这件唐代金银器出土于西安市何家村唐代窖藏。应结合金属薄厚、锤揲起伏、焊接接缝和錾刻纹样观看。金银延展性强，工匠可以用较薄的材料制造饱满体积，再以局部镶嵌、鎏金或细密刻划组织光泽，使结构和装饰在同一表面上发生。"
