      "cardLead": "这件唐代金银器出土于西安市何家村唐代窖藏。它以细金条塑出长颈、拱背、四肢和上扬的尾部，体量很小，行走姿态却由关节转折清楚地建立起来。",
      "essay": [
        {
          "heading": "器物与形制",
          "text": "这件唐代金银器出土于西安市何家村唐代窖藏。它以细金条塑出长颈、拱背、四肢和上扬的尾部，体量很小，行走姿态却由关节转折清楚地建立起来。头部、角、吻部与身上的刻划集中在有限表面内；成组陈列时，各件朝向和步态略有差异，说明它们不是一件大型雕塑的零件，而是一组可以分别观看的微型金器。"
        },
        {
          "heading": "历史意义",
          "text": "何家村窖藏中成组出现的微型金龙，把贵金属工艺、唐代仪式活动与窖藏主人的生活圈层联系在一起。研究者常把这类走龙与道教投龙仪式相联系；器物能够直接确认的是金质、成组、微型走兽形态及窖藏关系，具体用途仍需与出土组合和文献互证。其价值正在于，一组极小的金器同时保存了高水平塑形能力与唐代信仰实践的线索。"
        }
      ],
      "evidence": "名称、时代与来源优先取自 DSC_4660 中与画面中心器物对应的展签；说明牌只用于文字提取，不作为文物图片展示。可见器物图为 DSC_4659，现场原片保存在 F:\\DCIM\\102NCZ_F。",
