      "tags": [
        "forbidden"
      ],
      "tagsText": "forbidden",
      "summary": "唐 · 玉石器 · 西安市何家村唐代窖藏出土",
      "cardLead": "五彩缠丝玛瑙随色带琢成兽角形杯，兽嘴金塞可启闭出酒；产地与制作地仍有学术争议。",
      "essay": [
        {
          "heading": "出土与定级",
          "text": "镶金兽首玛瑙杯 1970 年出土于西安南郊何家村唐代窖藏，现藏陕西历史博物馆；高 6.5 厘米、长 15.6 厘米、口径 5.6 厘米。它列入 2002 年首批禁止出国（境）展览文物目录，馆方公开资料称其为目前所见唐代唯一一件俏色玉雕。"
        },
        {
          "heading": "材料、造型与出酒方式",
          "text": "整杯随一块五彩缠丝玛瑙的天然色带琢成兽角形，前端为圆睁双目的牛形兽首，两只弯角向后与杯身衔接。兽嘴上的金饰不是单纯点缀，而是可以拔取的出酒塞；工匠以“依色取巧、随形变化”的方式安排兽首、角和杯腹，使石材纹理直接参与造型。"
        },
        {
          "heading": "来通传统与珍稀性",
          "text": "兽角形出液酒具与西亚、中亚的来通传统相近，说明唐代长安能够接触并重新使用远方器形；但玛瑙原料、产地和制作地点仍有争议，不能把它武断写成进口品。它的不可替代性来自完整出土关系、罕见材料、俏色设计与可实际出酒的结构同时保存，而不是泛泛的“中西交流”四字。"
        }
      ],
      "evidence": "名称、时代与来源优先取自 DSC_4681 中与画面中心器物对应的展签；说明牌只用于文字提取，不作为文物图片展示。可见器物图为 DSC_4675—DSC_4680，现场原片保存在 F:\\DCIM\\102NCZ_F。",
