      "essay": [
        {
          "heading": "器物与形制",
          "text": "这件宋代铜器的具体出土地点未见于现有展签。口沿、杯腹、附耳与底足围绕持握和饮用安排；鎏金、刻铭或双耳又会改变观看重点。纹饰分区与器形转折同步铸成；若保存铭文，作器者、受命事件或宗族称谓还会把这件器物接入具体历史。"
        },
        {
          "heading": "历史意义",
          "text": "五代以后，窑业、金属加工、城市消费与长距离贸易改变了器物的生产和流通。旧器形仍被沿用，但配方、烧造和使用场景不断调整。这类器物的关键动作是盛放与取用。口沿缺口、腹内残留、底足磨损和出土位置若能彼此印证，才可区分宴饮、储藏、供奉或随葬；名称本身不能替代用途判断。"
        }
      ],
      "evidence": "名称、时代与来源优先取自 DSC_4731 中与画面中心器物对应的展签；说明牌只用于文字提取，不作为文物图片展示。可见器物图为 DSC_4730，现场原片保存在 F:\\DCIM\\102NCZ_F。",
