        {
          "heading": "器物与形制",
          "text": "这件公元前2世纪后半叶—前1世纪早期金属 / 珍珠复合出土于基克拉迪群岛提洛岛面具之宅。它以环体、连接件和垂饰组织佩戴时的正面效果。细金丝、金珠、薄片与微型人物必须同时解决重量、活动度和牢固程度；静置时看似对称的构图，佩戴后还会随身体运动产生轻微摆动和反光。"
        },
        {
          "heading": "跨区域传播",
          "text": "它来自希腊化世界持续流动的图像与工艺网络。王国、港口、商路和宗教仪式不断改写所谓“希腊风格”；材料来源、制作方法与出土地点结合后，才能看出一件小型器物如何参与地中海与近东之间的交流。 本次陈列见于“文明以止——希腊化时期的黄金艺术”特展。"
        }
