          "text": "它所属的酒神形象体系连接葡萄酒、节庆、戏剧与狂欢仪式。人物的姿态、植物属性和随从身份并非随意装饰，而是帮助观看者在很小的器物表面识别一整套神话关系与表演文化。 本次陈列见于“文明以止——希腊化时期的黄金艺术”特展。"
