      "essay": [
        {
          "heading": "器物与形制",
          "text": "这件公元前330—前320年陶器出土于马其顿佩拉东墓地。应从口沿、盖、腹部、足座和双耳之间的比例理解用途，再观察黑釉或红绘图像如何顺应曲面展开。器形提供盛装、婚礼或妆奁等实际功能，绘画和附加装饰则把具体仪式与神话叙事带入使用现场。"
        },
        {
          "heading": "跨区域传播",
          "text": "它来自希腊化世界持续流动的图像与工艺网络。王国、港口、商路和宗教仪式不断改写所谓“希腊风格”；材料来源、制作方法与出土地点结合后，才能看出一件小型器物如何参与地中海与近东之间的交流。 本次陈列见于“文明以止——希腊化时期的黄金艺术”特展。"
        }
      ],
