      "summary": "公元前4世纪晚期 · 金银器 · 展签来源未完整记录",
      "cardLead": "这件公元前4世纪晚期金银器的具体出土地点未见于现有展签。它以环体、连接件和垂饰组织佩戴时的正面效果。",
      "essay": [
        {
          "heading": "器物与形制",
          "text": "这件公元前4世纪晚期金银器的具体出土地点未见于现有展签。它以环体、连接件和垂饰组织佩戴时的正面效果。细金丝、金珠、薄片与微型人物必须同时解决重量、活动度和牢固程度；静置时看似对称的构图，佩戴后还会随身体运动产生轻微摆动和反光。"
        },
        {
          "heading": "音乐、神话与身份",
          "text": "它把音乐直接置入首饰或微型雕像：潘神的排箫、缪斯的艺术职掌，或弦乐器的持奏姿态，使声音获得了可佩戴、可观看的形象。音乐在这里同时关联诗歌教育、神祇崇拜和宴饮仪式；器物的价值正在于人物身份、乐器形制与佩戴场景被压缩在同一件作品中。 本次陈列见于“文明以止——希腊化时期的黄金艺术”特展。"
        }
      ],
      "evidence": "名称、时代与来源优先取自 DSC_4782 中与画面中心器物对应的展签；说明牌只用于文字提取，不作为文物图片展示。可见器物图为 DSC_4781，现场原片保存在 F:\\DCIM\\102NCZ_F。",
