          "text": "这件公元前350—前325年陶器的具体出土地点未见于现有展签。应从口沿、盖、腹部、足座和双耳之间的比例理解用途，再观察黑釉或红绘图像如何顺应曲面展开。器形提供盛装、婚礼或妆奁等实际功能，绘画和附加装饰则把具体仪式与神话叙事带入使用现场。"
