      "cardLead": "这件公元前3世纪—前2世纪早期金银器出土于马其顿安菲波利斯地区的一处墓葬。它依靠链节、珠串、中心饰件和垂坠部分建立胸前的层次。",
      "essay": [
        {
          "heading": "器物与形制",
          "text": "这件公元前3世纪—前2世纪早期金银器出土于马其顿安菲波利斯地区的一处墓葬。它依靠链节、珠串、中心饰件和垂坠部分建立胸前的层次。金银器的颗粒、绞丝、镶嵌和连接孔既构成装饰，也决定首饰能否随身体弧度自然下垂；中心图像通常承担最明确的身份或神话指向。"
        },
        {
          "heading": "护佑与婚姻象征",
          "text": "它以交缠而难以自行松脱的结式构成视觉中心。赫拉克勒斯结在希腊化首饰中兼具力量、护佑与婚姻联想，结构本身因此就是意义载体；它也显示一种母题如何随金匠、王国和贸易网络跨区域传播。 本次陈列见于“文明以止——希腊化时期的黄金艺术”特展。"
        }
      ],
