      "tagsText": "wall forbidden",
      "summary": "用户补入资料图 · 四幅未现场拍摄的壁画",
      "cardLead": "九名宫女在女官引领下持方盒、杯、拂尘、如意、团扇与蜡烛徐行，服饰和职掌各有线索。",
      "essay": [
        {
          "heading": "前室东壁的九人队列",
          "text": "《宫女图》绘于唐永泰公主墓前室东壁南侧，1960 年发掘，现藏陕西历史博物馆；画面约高 177 厘米、宽 198 厘米，并以一组列入第三批禁止出境展览文物目录。馆方称其为永泰公主墓中保存最完整的女性群像之一。"
        },
        {
          "heading": "发式、服装与持物",
          "text": "九名宫女在女官引领下缓步前行，头梳不同高髻，肩披纱巾，长裙曳地。她们分别持方盒、酒杯、拂尘、如意、团扇和蜡烛等物，有人低语、有人回顾、有人凝神；器物和视线把相似服装中的人物分出职掌与动作。"
        },
        {
          "heading": "宫廷服务制度的图像档案",
          "text": "这幅画不能只归入“唐代仕女之美”。九人队列、手中器物、男式袍衫与女性衣裙、墓室位置共同记录宫廷侍从怎样围绕墓主人组织服务，也为服饰、发式和女性生活研究提供有年代依据的材料；群像与墓葬原位不可拆分，构成其珍稀性。"
        }
      ],
      "evidence": "此图为用户补入的资料图，不是本次现场拍摄；用于补齐未展出或未能现场拍摄的四件壁画条目。",
